public function testInvalidConfiguration(array $config, string $exceptionExpression): void
{
    $this->expectException(InvalidFixerConfigurationException::class);
    $this->expectExceptionMessageMatches($exceptionExpression);

    $this->fixer->configure($config); // @phpstan-ignore argument.type
}

public function testFix(string $expected, ?string $input = null, array $configuration = []): void
{
    $this->fixer->configure($configuration);
    $this->doTest($expected, $input);
}

public function testClassyDefinitionInfo(string $source, array $expected): void
{
    Tokens::clearCache();
    $tokens = Tokens::fromCode($source);

    $result = \Closure::bind(static fn (ClassDefinitionFixer $fixer): array => $fixer->getClassyDefinitionInfo($tokens, $expected['classy']), null, ClassDefinitionFixer::class)($this->fixer);

    ksort($expected);
    ksort($result);

    self::assertSame($expected, $result);
}

public function testWithWhitespacesConfig(string $expected, ?string $input = null): void
{
    $this->fixer->setWhitespacesConfig(new WhitespacesFixerConfig("\t", "\r\n"));
    $this->doTest($expected, $input);
}
